// Local Python API adapter; shared by Live Scan and DriveScan. No UI redesign.
const visionService={online:false,modelLoaded:false,potholeLoaded:false,checking:false,error:'',url:'',poll:null};
scan.frameInterval=Math.max(500,Number(window.CIVICEYE_VISION_ENV?.frameIntervalMs)||700);
function visionUrls(){
  const config=window.CIVICEYE_VISION_ENV||{};
  if(!config.visionApiUrl)throw Error('AI SERVICE OFFLINE — production API URL is not configured.');
  const base=new URL(config.visionApiUrl);
  if(config.production&&base.protocol!=='https:')throw Error('AI SERVICE OFFLINE — HTTPS API required.');
  return {detect:new URL('/detect',base).href,health:new URL('/health',base).href};
}
visionReady=function(){return visionService.online&&visionService.modelLoaded};
async function checkVisionHealth(){if(visionService.checking)return;visionService.checking=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),3000);try{const {health}=visionUrls();const response=await fetch(health,{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error('AI service offline');const data=await response.json();if(data.status!=='online'||typeof data.model_loaded!=='boolean')throw Error('Invalid AI service health response');visionService.online=true;visionService.modelLoaded=data.model_loaded;visionService.potholeLoaded=data.pothole_detector===true;visionService.ready=data.ready!==false;visionService.error=data.model_error||data.pothole_error||'';if(scan.mode==='live'&&!scan.paused){if(!data.model_loaded){scan.status='AI SERVICE CONNECTED — MODEL NOT LOADED';scan.detections=[]}else if(scan.camera&&!scan.busy){scan.status=scan.detections.length?'Detection found':'Scanning…';scheduleScan(0)}else if(!scan.camera)scan.status=data.pothole_detector!==true?'GARBAGE / WATERLOGGING READY — POTHOLE UNAVAILABLE':'MODEL LOADED / LIVE AI READY'}}catch(e){visionService.online=false;visionService.modelLoaded=false;visionService.error=e.name==='AbortError'?'AI SERVICE OFFLINE — backend health check timed out.':e.message.startsWith('AI SERVICE OFFLINE')?e.message:'AI SERVICE OFFLINE — backend unavailable. Please retry shortly.';if(scan.mode==='live'){scan.status='AI SERVICE OFFLINE';scan.detections=[];scan.feed=scan.feed.filter(finding=>finding.demo)}}finally{clearTimeout(timeout);visionService.checking=false;updateScanUi()}}
detectFrame=async function(image,signal){const response=await fetch(visionUrls().detect,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image,timestamp:now()}),signal});let data;try{data=await response.json()}catch{throw Error('AI detection temporarily unavailable. Invalid server response.')}if(!response.ok||data.success!==true){if(data.error==='MODEL_NOT_LOADED'){visionService.online=true;visionService.modelLoaded=false;throw Error('AI service connected — local ONNX model not loaded. Check backend model files.')}throw Error('AI detection temporarily unavailable. '+(data.message||data.error||`HTTP ${response.status}`))}visionService.online=true;visionService.modelLoaded=true;visionService.ready=data.ready!==false;visionService.error=(data.warnings||[]).join(' ');return {detections:validateDetectionResponse(data),processingTimeMs:data.processingTimeMs}};
function boxOverlap(a,b){if(!a||!b)return 0;const width=Math.max(0,Math.min(a.x+a.width,b.x+b.width)-Math.max(a.x,b.x)),height=Math.max(0,Math.min(a.y+a.height,b.y+b.height)-Math.max(a.y,b.y));const inter=width*height;return inter/Math.max(1e-9,a.width*a.height+b.width*b.height-inter)}
saveFinding=function(d,image,demo,analysis){const recent=scan.feed.find(f=>f.detection.class===d.class&&f.demo===demo&&Date.now()-new Date(f.lastSeen||f.time)<10000&&(d.bbox&&f.detection.bbox?boxOverlap(d.bbox,f.detection.bbox)>=.35:!d.bbox&&!f.detection.bbox));if(recent){recent.lastSeen=now();recent.currentBox=d.bbox;if(d.confidence===null||d.confidence>recent.detection.confidence){recent.detection=d;recent.image=image;recent.analysis=analysis}return}scan.feed.unshift({detection:d,image,demo,time:now(),lastSeen:now(),analysis,latitude:state.position?.latitude,longitude:state.position?.longitude});scan.feed=scan.feed.slice(0,30)};
let overlayObserver=null,observedOverlay=null;
function drawVisionOverlay(){const host=$('#detection-boxes');if(!host)return;let canvas=host.querySelector('canvas');if(!canvas){host.replaceChildren();canvas=document.createElement('canvas');canvas.setAttribute('aria-label','Detection bounding boxes');canvas.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none';host.append(canvas)}const rect=host.getBoundingClientRect(),ratio=window.devicePixelRatio||1;if(!rect.width||!rect.height)return;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.lineWidth=2;ctx.font='600 12px DM Sans, sans-serif';for(const d of scan.detections){if(!d.bbox)continue;const b=d.bbox,x=b.x*rect.width,y=b.y*rect.height,w=b.width*rect.width,h=b.height*rect.height,color={pothole:'#a9793d',garbage:'#268873',waterlogging:'#427e9e'}[d.class];ctx.strokeStyle=color;ctx.strokeRect(x,y,w,h);const label=displayType(d.class).toUpperCase()+' '+confidenceText(d)+(scan.mode==='demo'?' · DEMO':''),labelWidth=Math.min(rect.width,ctx.measureText(label).width+12),labelX=Math.max(0,Math.min(x,rect.width-labelWidth)),labelY=Math.max(0,y);ctx.fillStyle=color;ctx.fillRect(labelX,labelY,labelWidth,23);ctx.fillStyle='white';ctx.fillText(label,labelX+6,labelY+16,labelWidth-12)}if(observedOverlay!==host){overlayObserver?.disconnect();overlayObserver=new ResizeObserver(drawVisionOverlay);overlayObserver.observe(host);observedOverlay=host}}
const previousScanUi=updateScanUi;updateScanUi=function(){previousScanUi();if(!scanScene()||!$('#model-connection'))return;let service=$('#service-connection');if(!service){service=document.createElement('span');service.id='service-connection';$('#model-connection').before(service)}service.textContent='AI service: '+(visionService.checking&&!visionService.online?'checking':visionService.online?'connected':'offline');$('#model-connection').textContent='AI model: '+(scan.mode==='demo'?'demo — not analyzed':visionService.online?(visionService.modelLoaded?'loaded':'model required'):'offline');if(scan.mode==='live'&&visionService.modelLoaded&&!visionService.potholeLoaded){$('#model-connection').textContent='Garbage / waterlogging loaded · pothole not ready';$('#live-error').textContent=visionService.error||'Pothole analysis is pending.'}if(scan.mode==='live'&&!visionService.modelLoaded){$('#scan-message').textContent=visionService.online?'AI SERVICE CONNECTED — MODEL NOT LOADED':'AI SERVICE OFFLINE';if(visionService.error&&!scan.error)$('#live-error').textContent=visionService.error}drawVisionOverlay()};
const previousScanBind=bindLiveScan;bindLiveScan=function(){previousScanBind();if(window.CIVICEYE_VISION_ENV?.production&&$('#vision-settings')){const form=$('#vision-settings');form.elements.endpoint.value=visionUrls().detect;form.elements.endpoint.readOnly=true;form.querySelectorAll('button').forEach(button=>button.disabled=true);form.onsubmit=event=>event.preventDefault()}clearInterval(visionService.poll);if(!scanScene()){overlayObserver?.disconnect();observedOverlay=null;return}checkVisionHealth();visionService.poll=setInterval(()=>{if(scanScene())checkVisionHealth()},5000)};
const previousScanStop=stopScan;stopScan=function(){previousScanStop();overlayObserver?.disconnect();observedOverlay=null};
render();
